/**
 * Adapter from OberonScanner to java_cup.runtime.Scanner.
 * Maps Token.Type to the sym constants generated by JavaCUP.
 *
 * @author Lin Hongyu
 * @version 1.00
 */
import java_cup.runtime.Symbol;
import java.io.IOException;
import exceptions.*;

public class ScannerAdapter implements java_cup.runtime.Scanner {
    private OberonScanner scanner;
    private static final java.util.Map<Token.Type, Integer> symMap = new java.util.HashMap<>();

    static {
        // Map Token.Type -> Sym constants (generated by JavaCUP from oberon.cup)
        symMap.put(Token.Type.MODULE,     Sym.MODULE);
        symMap.put(Token.Type.END,        Sym.END);
        symMap.put(Token.Type.PROCEDURE,  Sym.PROCEDURE);
        symMap.put(Token.Type.BEGIN,      Sym.BEGIN);
        symMap.put(Token.Type.CONST,      Sym.CONST);
        symMap.put(Token.Type.TYPE,       Sym.TYPE);
        symMap.put(Token.Type.VAR,        Sym.VAR);
        symMap.put(Token.Type.ARRAY,      Sym.ARRAY);
        symMap.put(Token.Type.OF,         Sym.OF);
        symMap.put(Token.Type.RECORD,     Sym.RECORD);
        symMap.put(Token.Type.IF,         Sym.IF);
        symMap.put(Token.Type.THEN,       Sym.THEN);
        symMap.put(Token.Type.ELSIF,      Sym.ELSIF);
        symMap.put(Token.Type.ELSE,       Sym.ELSE);
        symMap.put(Token.Type.WHILE,      Sym.WHILE);
        symMap.put(Token.Type.DO,         Sym.DO);
        symMap.put(Token.Type.DIV_KW,     Sym.DIV_KW);
        symMap.put(Token.Type.MOD_KW,     Sym.MOD_KW);
        symMap.put(Token.Type.OR,         Sym.OR);
        symMap.put(Token.Type.RETURN,     Sym.RETURN);
        symMap.put(Token.Type.IDENTIFIER,         Sym.IDENTIFIER);
        symMap.put(Token.Type.INTEGER_LITERAL,    Sym.INTEGER_LITERAL);
        symMap.put(Token.Type.PLUS,       Sym.PLUS);
        symMap.put(Token.Type.MINUS,      Sym.MINUS);
        symMap.put(Token.Type.STAR,       Sym.STAR);
        symMap.put(Token.Type.SLASH,      Sym.SLASH);
        symMap.put(Token.Type.EQ,         Sym.EQ);
        symMap.put(Token.Type.NE,         Sym.NE);
        symMap.put(Token.Type.LT,         Sym.LT);
        symMap.put(Token.Type.LE,         Sym.LE);
        symMap.put(Token.Type.GT,         Sym.GT);
        symMap.put(Token.Type.GE,         Sym.GE);
        symMap.put(Token.Type.AND,        Sym.AND);
        symMap.put(Token.Type.NOT,        Sym.NOT);
        symMap.put(Token.Type.ASSIGN,     Sym.ASSIGN);
        symMap.put(Token.Type.LPAREN,     Sym.LPAREN);
        symMap.put(Token.Type.RPAREN,     Sym.RPAREN);
        symMap.put(Token.Type.LBRACKET,   Sym.LBRACKET);
        symMap.put(Token.Type.RBRACKET,   Sym.RBRACKET);
        symMap.put(Token.Type.DOT,        Sym.DOT);
        symMap.put(Token.Type.COMMA,      Sym.COMMA);
        symMap.put(Token.Type.SEMICOLON,  Sym.SEMICOLON);
        symMap.put(Token.Type.COLON,      Sym.COLON);
        // EOF is reserved in CUP, use 0
        symMap.put(Token.Type.EOF,        0);
    }

    public ScannerAdapter(OberonScanner scanner) {
        this.scanner = scanner;
    }

    @Override
    public Symbol next_token() throws Exception {
        Token t = scanner.nextToken();
        int sym = symMap.getOrDefault(t.getType(), -1);
        return new Symbol(sym, t.getLine(), t.getColumn(), t.getLexeme());
    }
}
